import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene placement
  const pos = config.scenePosition || [3.2, 1, 0.06];
  group.position.set(pos[0], pos[1], pos[2]);

  const rot = config.sceneRotation || [0, 0, 0];
  group.rotation.set(rot[0], rot[1], rot[2]);

  const scale = config.sceneScale || [1, 1, 1];
  group.scale.set(scale[0], scale[1], scale[2]);

  // Design token colors
  const colors = config.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // Load texture (cached via ctx)
  const textureMap = ctx.textureLoader.load(
    config.assets?.imageUrl || '/prism-mock/home/nodes/floating-accent.png'
  );
  textureMap.colorSpace = THREE.SRGBColorSpace;

  // Create textured plane (512x320 image = 1.6:1 aspect ratio)
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);
  const textureNode = texture(textureMap);
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: textureNode,
    transparent: true,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Add text via font atlas
  const textContent = config.textContent || 'Journal 3';
  if (ctx.fontAtlas) {
    const textMesh = ctx.fontAtlas.createMesh({
      text: textContent,
      size: 0.34, // headline size from design tokens
      weight: 400,
      font: 'Lora',
      color: colors.ink,
    });
    if (textMesh) {
      textMesh.position.z = 0.01; // Render text in front
      group.add(textMesh);
    }
  }

  // Store original position for animations
  const originalY = group.position.y;
  let isHovering = false;

  // Interaction handlers
  group.userData.handlers = {
    hover: () => {
      if (isHovering) return;
      isHovering = true;
      // rise-in: move up 0.15 scene units over 0.7s
      gsap.to(group.position, {
        y: originalY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    unhover: () => {
      if (!isHovering) return;
      isHovering = false;
      // Return to original position
      gsap.to(group.position, {
        y: originalY,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    click: () => {
      // press-down: scale to 0.97 then back to 1.0
      gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
      gsap.to(group.scale, {
        x: 1,
        y: 1,
        duration: 0.12,
        ease: 'back.out',
        delay: 0.12,
      });
      // Emit hub-journal.select event
      config.onSelect?.();
    },
  };

  // Cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureMap.dispose();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
  };

  return group;
}
